def reconstruct_ring(N, sums):
    # Initialize the original ring with zeros
    original = [0] * N

    # Set the first element to an arbitrary value
    original[0] = sums[0] // 2

    # Reconstruct the rest of the elements
    for i in range(1, N):
        original[i] = sums[i] - sums[i-1] - original[i-1]

    # Ensure all values are non-negative
    min_value = min(original)
    if min_value < 0:
        for i in range(N):
            original[i] -= min_value

    # Adjust the first element to ensure the correct sum
    original[0] = sums[0] - original[1] - original[-1]

    # Verify the solution
    for i in range(N):
        if original[i] < 0 or original[(i+1) % N] + original[i] + original[(i-1) % N] != sums[i]:
            raise ValueError("No valid solution found")

    return original

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    sums = list(map(int, data[1:]))

    try:
        original = reconstruct_ring(N, sums)
        for num in original:
            print(num)
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()

